// Original teaching text and small worked examples, not excerpts from the linked sources.
const sources={stages:['公开配方对照：Olmo 3','https://allenai.org/blog/olmo3'],mid:['SmolLM3 的训练阶段','https://huggingface.co/blog/smollm3'],sft:['TRL SFT Trainer','https://huggingface.co/docs/trl/sft_trainer'],ppo:['PPO 原论文','https://arxiv.org/abs/1707.06347'],grpo:['DeepSeekMath / GRPO','https://arxiv.org/abs/2402.03300'],dpo:['DPO 原论文','https://arxiv.org/abs/2305.18290'],mopd:['Multi-Teacher On-Policy Distillation','https://arxiv.org/abs/2606.30406'],rl:['强化学习交互框架','https://huggingface.co/learn/deep-rl-course/en/unit1/rl-framework'],lora:['LoRA 原论文','https://arxiv.org/abs/2106.09685'],qlora:['QLoRA 原论文','https://arxiv.org/abs/2305.14314'],draft:['DRaFT：生成模型的奖励微调','https://arxiv.org/abs/2309.17400']};
const unit=(id,goal,terms,steps,worked,practice,check,refs,extra={})=>({id,goal,terms:terms.map(([name,meaning])=>({name,meaning})),steps:steps.map(([title,...body])=>({title,body})),worked,practice:{action:practice[0],expected:practice[1],trouble:practice[2]},check:{prompt:check[0],options:check[1],answer:check[2],explanation:check[3]},sources:refs.map(k=>({label:sources[k][0],url:sources[k][1]})),...extra});
export const trainingUnits=[
 unit('why-stages','从一次训练的限制推导分阶段训练，而非背诵三个缩写。',[
 ['基座','已在某种数据与目标上学到能力、可以继续训练的模型；不是一种固定结构。'],['训练阶段','团队为了数据、目标、预算或验收而划分的训练区间。']],
 [['先观察同一个模型的两种失败','一个续写模型看到“请返回 JSON”，可能接着写一篇介绍 JSON 的文章。它会语言，却未必把这句话当作必须执行的指令。另一方面，格式完全正确的回答也可能缺乏领域知识。这是两个不同缺口。'],['为什么不能把所有数据一次混进去','技术上可以混合多种数据，但稀少的高质量示范容易被大量普通文本淹没，各目标还可能竞争。分阶段便于控制数据比例、改变 loss、保存对照点和停止条件。分阶段是可管理的配方选择，不是数学定律。'],['工程上真正变化的地方','保留 tokenizer、模型结构与参数形状，换 data/ 中的采样器，可能换 training/ 中的目标，再由 eval/ 分域比较。若换结构，要另外处理权重迁移；不能把结构变化藏在“继续训练”四个字里。']],
 ['A 快照：能续写资料，指令格式成功率低。','B 快照：加入领域原文后，领域验证 loss 降低，但格式仍不稳定。','C 快照：用问答示范训练后，格式成功率提高；仍要复测一般文本能力。'],
 ['为“回答产品手册问题”画 A→B→C，每个箭头填写数据、目标和验收。','A 用一般原文，B 用领域原文，C 用指令示范；每步保存来源与通用/领域/任务评测。','如果只写“预训练→SFT”而没有数据和目标，再补上每个 batch 输入与标签。'],
 ['分阶段训练首先帮助我们做什么？',['控制数据、目标与验收，定位能力变化','保证每个模型必须恰好训练三次','自动解决所有能力冲突'],0,'阶段是组织实验的边界。它不会自动带来更强能力，也不固定次数。'],['stages']),
 unit('three-stages','按要解决的问题理解预训练、中训练与后训练。',[
 ['预训练','为后续应用建立基础表示或生成能力的训练。'],['中训练','部分配方对基座之后、最终适配之前的能力强化阶段的称呼，边界依项目而异。'],['后训练','在已有模型上，使任务表现、交互行为或偏好更符合使用要求的一组训练活动。']],
 [['沿能力看，而不是沿文件名猜','语言预训练常让模型预测下一个 token。领域持续训练可以保持同一目标，却换为更多专业文本。后训练可能用任务示范、偏好或奖励。三个阶段完全可能沿用同一个 Decoder-only 骨干。'],['中训练确实存在，但不是通用硬标准','有的项目把高质量数据退火、长上下文训练归入预训练后段；有的单列 mid-training；有的把推理适配放入更广义的 post-training。课程单列中训练，是为了能看清这类能力补强，不要求所有论文服从同一目录。'],['怎样读一次实际训练','先找起始 checkpoint，再找数据混合、样本模板、loss 与 trainable 参数；最后看进入下一阶段的判据。名称只帮助索引，不替代这些证据。PT 还可能在团队里指 pretraining 或 post-training，必须查上下文。']],
 ['普通文本→预测下一个 token：建立语言基座。','专业原文→同样预测下一个 token：持续预训练/领域适配，可位于中训练。','问题+答案→只监督答案：常见 SFT；仍使用 token 交叉熵，但使用目的和监督区域已变。'],
 ['给三条样本分别标注阶段、目标、监督位置；再写一个无法仅凭名字定类的例子。','能说明“同样交叉熵”不等于“同一阶段”；PT 文件夹不能直接判定含义。','如果按数据是否有人标注分类，注意原文也可能人工筛选；应看怎样产生训练信号。'],
 ['保持 next-token loss、增加领域原文，一定是 SFT 吗？',['是，只要接着训练就叫 SFT','否，还要看任务模板和监督目的；常见为持续预训练','是，只要使用 LoRA'],1,'继续更新参数只是事实。原文能力适配与示范任务训练要进一步区分。'],['stages','mid']),
 unit('axes','让 SFT、LoRA、AR、KDA、PPO 各就其位。',[
 ['结构','数据怎样经过模块计算，如 Transformer、SSM。'],['目标','希望提高什么量，如正确 token 的概率或期望奖励。'],['更新范围','哪些参数参与优化，如全量更新或低秩适配器。']],
 [['先把描述拆成独立列','阶段回答何时、为何训练；模态回答处理什么；结构回答如何计算；生成分解回答输出如何组织；loss/算法回答如何学习；更新范围回答改哪些参数；执行工程回答如何跑得动。一个模型必须同时在多列上做选择。'],['把一句话逐层展开','“用 LoRA 对 Decoder-only 模型做 SFT”：骨干仍是因果 Transformer，数据是示范问答，目标通常是回答 token 交叉熵，底座权重被冻结，低秩增量可训练。没有任何矛盾。'],['避免跨层比较','DINO 是视觉表征学习方法/模型系列，视觉塔是系统角色；KDA 是序列混合机制，MOPD 是蒸馏路线。讨论替换时，先确认接口与层级。更换 SFT 为偏好训练不等于更换视觉塔。']],
 ['数据：问题→示范回答；目标：提高回答概率。','结构：Decoder-only；生成：AR；更新：LoRA。','实现：混合精度与梯度累积；阶段：后训练。七列描述同一次实验。'],
 ['在实验手记建立七列，填入一个已读项目；未知列明确写待查证。','能找到具体配置或代码证据；不会把 LoRA 与 SFT 放进只能二选一的菜单。','如果某名称属于多列，写出具体版本和本次含义，不强行只贴一个标签。'],
 ['KDA 与 MOPD 的合理关系是？',['两种互斥的注意力结构','序列计算机制可以与多教师蒸馏训练路线组合','二者都是数据评测集'],1,'它们解决不同层的问题；能否实际组合仍取决于接口、训练实现与预算。'],['lora','mopd']),
 unit('stage-boundaries','用公开配方核对阶段含义，不把本书目录当成行业统一定义。',[
 ['训练配方','数据、模型、优化器、日程、目标和评测的组合。'],['能力门槛','进入下一阶段所要求的证据，而不是固定训练天数。']],
 [['为什么不同团队会切分不同','起点不同、领域数据规模不同、最终用途不同，都会改变阶段安排。已有强基座的小团队可能直接做 SFT；从零做基座的项目需要更完整的数据和算力日程。'],['比较时使用同一张表','分别记录：输入 checkpoint、输出 checkpoint、训练样本、loss、可训练模块、上下文长度、评测。再把论文中的阶段名放到最左列。这样能发现同名不同义、异名近似的情况。'],['不要把例外变成强制路线','并非所有奖励优化都必须先训练一个奖励模型，也并非所有模型都必须经相同 SFT→DPO→RL 顺序。是否需要该步骤取决于起始能力、反馈信号和实验结果。']],
 ['配方 A：基座→指令示范→偏好优化。','配方 B：基座→领域/长文本适配→任务示范。','两者都可以合理；若没有长输入需求，不能凭目录要求 B 必须发生。'],
 ['打开本页两个官方来源，各抄录阶段名称，并用自己的话填数据/目标/评测三列。','得到有来源的比较表，而不是宣称某个团队命名错误。','不确定某阶段监督位置时，标注未知并查数据模板；不能从文章标题猜。'],
 ['两个报告对 mid-training 分界不同，应当怎样处理？',['用本书定义判定其中一个错误','核对实际数据、目标与产物，并保留各自命名','忽略所有中训练内容'],1,'比较实际训练操作比争论标签更有用。'],['stages','mid']),
 unit('data-quality','让数据处理服务于监督目标，并防止泄漏和重复占用预算。',[
 ['去重','识别重复或近重复样本；应明确按文档、片段还是语义处理。'],['数据配比','训练时从各来源抽样的比例，不等于磁盘文件大小比例。']],
 [['先划分再处理跨集合重复','先定义评测边界，例如按文档、用户或 episode 隔离。训练集与验证集共享同一段内容时，低 loss 可能只是记忆。近重复检测应跨集合核查；不要为了提高成绩把难评测样本删除。'],['质量是任务相关的','乱码、断裂模板、错位标签通常有害；但口语、不常见语言或困难样本不等于低质量。记录每条过滤规则的保留率，并抽样审查被删内容，避免筛出一份只像评测集的数据。'],['配比怎样改变学习','假设通用数据 9000 条、领域数据 1000 条，按文件均匀采样只有 10% 领域样本。改成 50:50 会反复看到领域数据，增加曝光也增加过拟合风险。比较时保持总 token 预算并报告各域有效 token。']],
 ['总预算 1000 个有效 token，领域占 30%，通用占 70%。','若领域平均 loss=1、通用=3，配比加权平均为 0.3×1+0.7×3=2.4。','只报告混合 loss 会掩盖分域变化；同一配比才能直接比较混合值。'],
 ['实现下方配比函数，随后把领域比例从 0.3 改为 0.9，解释平均值下降是否证明模型进步。','2.4 变成 1.2 可以完全由比例变化造成；必须固定评测集。','混合分母应是权重总和；拒绝负数、全零权重和非有限输入。'],
 ['只改评测配比，平均 loss 降低能证明训练改进吗？',['可以，loss 总是越低越好','不可以，评测分布变了','只要样本更多就可以'],1,'需要在同样评测分布与分域指标上对照。'],['stages'],{exerciseId:'book-mixture'}),
 unit('modality-pretrain','把同一个训练闭环迁移到不同模态，先找监督从哪里来。',[
 ['自监督','监督信号由数据自身及构造规则产生，不必逐条人工标注目标。'],['条件变量','希望生成或预测依赖的信息，如文字、历史帧或动作。']],
 [['语言：遮住未来来预测','把一段文本错开一位，就得到输入和目标。因果 mask 阻止看到目标对应的未来内容。随机初始化的语言模型先学常见模式，再随数据和容量学习复杂依赖；小模型不保证出现大模型能力。'],['图像：目标不一定是类别','去噪训练从干净图像构造带噪输入，学习噪声、干净图像或相应参数化；Flow Matching 学给定时间的速度。DINO 一类方法学习增强视图之间的表征关系。视觉预训练不是单一“识别猫狗”。'],['视频：还要守住时间关系','连续片段需有一致时间戳、帧率及采样规则。预测下一帧、整段去噪、预测 latent 可以采用不同目标。若训练看到了未来帧而部署没有，该接口就可能不适用。']],
 ['语言：前文→下一个 token；信号来自原文。','生成：带噪 latent、时间、文字→噪声/速度；信号来自加噪构造。','世界模型：历史和动作→未来状态；信号来自同一 episode 的后续观测。'],
 ['为三种任务各画一条 batch 数据流，标明 target 与部署时可用输入。','区分“为监督读取未来”与“把未来错误放进输入”。','如果不能说清 loss 比较哪两个张量，回到第三卷对应模态章节。'],
 ['预训练是否只等于 next-token 预测？',['是','否，目标随任务与模态改变','只有用 Transformer 才叫预训练'],1,'next-token 是常见语言目标，不覆盖全部表示学习与生成训练。'],['stages']),
 unit('capability-gap','从分域证据定位能力缺口，决定是否真的需要继续训练。',[
 ['能力缺口','在目标输入分布上的具体失败，需由独立评测描述。'],['领域适配','让已有模型更适应某类数据、词汇、格式或任务分布。']],
 [['先区分三类失败','不知道资料内容、无法按格式作答、读不完长输入，是不同问题。第一个可能适合检索或领域训练，第二个可能适合模板约束/SFT，第三个需检查截断、位置机制与长度分布。先诊断能减少无效训练。'],['给每个猜想一个对照','让模型带着相关资料回答，如果明显改善，检索可能足够；固定信息改提示，观察格式；把长问题缩短，观察正确率。对照实验不能保证唯一原因，但能排除一部分猜测。'],['定义训练前的验收表','保留通用、领域、任务三类指标和失败样例。把将来要调参的验证集与最终测试集分开。没有训练前基线，就无法判断继续训练后的提升来自哪里。']],
 ['手册题错：先提供正确手册段落。','提供后正确：优先比较检索方案与继续训练的成本。','提供后仍错：检查指令理解、推理与标签，再决定训练目标。'],
 ['为一个失败写出至少两个可能原因，并设计只改变一项的测试。','得到“支持某原因”的证据，而不是“模型不够大”的泛泛结论。','如果同时换模型、数据和提示，无法归因；先固定两项。'],
 ['领域答错时最先应做什么？',['直接提高 LoRA rank','分解失败并建立对照','必定从零预训练'],1,'训练方法要服务于已确认的问题。'],['mid']),
 unit('cpt','在保持训练目标时改变数据分布，观察领域收益与通用退化。',[
 ['CPT','Continued Pretraining，持续预训练；从已有权重继续使用预训练类目标学习。'],['学习率日程','每步使用的步长安排，影响更新幅度与稳定性。']],
 [['最小工程改动','加载基座 checkpoint，沿用 tokenizer 和模型，把 sampler 换为领域与通用混合。语言 CPT 常继续 next-token loss，不自动加问答模板。记录是否重置优化器、全局步数与日程；两种选择都需明示。'],['不是数据越专越好','全部换成少量领域样本可能很快降低领域训练 loss，却记住句子或损伤一般能力。保留通用样本只是缓解策略之一，不是遗忘的保证解。需要同预算对照领域比例和学习率。'],['如何选择试验规模','先用少量训练步检查一个 batch、梯度和验证曲线，再扩预算。保留 base、低比例、高比例三组，不先做十个变量网格。用固定 token/step 预算和相同测试集比较。']],
 ['基座 A 保持不动，作为参照。','从 A 分别训练 B：30% 领域，C：90% 领域，总预算相同。','评测 B/C 的通用与领域 NLL；只能在测得结果后决定配比。'],
 ['完成“模型成长”实验的 mixed 与 domain_only 分支，保留报告和阶段快照。','能解释相同结构、相同 next-token 目标下，为什么仍产生不同能力分布。','不要从 B 继续训 C 再与 B 比；这会混入额外预算，应从同一个 A 出发。'],
 ['公平比较两种领域比例，哪种设计更合适？',['从同一基座出发、相同预算、固定评测','先训练 B，再在 B 上多训一倍得到 C','各自挑最有利的评测集'],0,'训练起点和预算是控制变量的一部分。'],['mid'],{links:[['运行成长实验','book','training/growth/growth-mid']]}),
 unit('context-extension','让“能接收更长输入”和“能利用更远信息”分别接受检验。',[
 ['上下文窗口','一次计算允许处理的序列长度及相应位置约束。'],['长度泛化','在训练长度之外仍能正确利用信息的能力，需要实测。']],
 [['先排除工程截断','tokenizer、collator、packing 和推理服务都可能截断输入。仅修改 max_length 不一定改变模型的位置机制，也不会自动学会远距离依赖。先检查真正进入模型的 token 数。'],['再看结构与训练','位置编码、注意力可见范围、KV cache 与算力限制一起决定可行长度。有些方法调整位置机制并做长序列训练；稀疏/滑窗注意力减少读取位置，但可能丢失远处信息。需把成本与信息损失同时记录。'],['专项能力需专项评测','把答案依据放在开头、中间、结尾，改变长度和干扰项，测准确率与资源。短文本能力也要回归测试。单一检索题只证明检索行为，不等于长篇推理、总结都提升。']],
 ['长度上限从 2k 改为 8k，服务成功接收输入。','中间位置的证据仍被忽略：说明可接收不等于会利用。','以长度×证据位置构成评测矩阵，再决定训练或结构改动。'],
 ['在结构实验室比较全局因果与 SWA 的可见位置，构造一个窗口外证据例子。','能指出哪些 query 无法直接读到证据，并提出多层传播或全局层的验证问题。','不要把理论可见位置直接等同实际准确率；模型还要学会使用它。'],
 ['把配置 max_length 加倍就完成长上下文适配了吗？',['是','否，还需检查输入、位置机制、训练和利用能力','只需扩大 batch'],1,'长度限制、信息路径和实际能力是三个相关但不同的问题。'],['mid'],{links:[['注意力可见性实验','architectures','lab']]}),
 unit('forgetting','读懂数据混合造成的权衡，而不是用总分掩盖能力退化。',[
 ['灾难性遗忘','适应新任务/分布后，旧能力明显退化的现象。'],['保留集','用于持续监控旧能力的固定评测集合，不参与本次训练。']],
 [['参数是共享资源','同一套参数服务多个输入分布。某域的梯度更新可能改变另一个域的行为；任务不同并不保证梯度彼此兼容。冻结部分模块、数据回放、小步长、正则或参数适配都只是可测试的手段。'],['混合指标会骗人','如果训练后领域 loss 下降、通用 loss 上升，换一个更偏领域的加权总分就可能宣布“全面提升”。报告必须保留分域结果、固定权重和样本量，不能只展示最好的单项。'],['提出有预算的取舍','先写门槛，例如通用 NLL 退化不超过自定阈值且领域改善。阈值由任务需求决定，不是行业统一值。若两者无法同时满足，要明确适用范围或保留多个 checkpoint。']],
 ['A：通用 1.0、领域 2.0；B：通用 1.5、领域 1.0。','等权均值 A=1.5，B=1.25，但通用变差 0.5。','若通用退化门槛为 0.2，B 仍不能通过；均值不能覆盖约束。'],
 ['用下方配比代码验证示例，再改权重，记录哪个结论随权重改变、哪个不变。','均值排序可变；通用退化 0.5 是固定评测下的分域事实。','把 train loss 当作保留能力证据会误判；应使用独立旧域数据。'],
 ['某域改善、旧域明显下降，怎样报告？',['只展示加权平均提升','同时展示分域变化与验收门槛','把旧域从评测删掉'],1,'权衡必须公开，才能判断这次更新是否适合目标应用。'],['mid'],{exerciseId:'book-mixture'}),
 unit('stage-gate','把“训练够了”改成可解释的进入条件。',[
 ['验证集','用于选配置、停止点与模型的独立数据。'],['测试集','在方案确定后用于最终评估，不能被反复用来调参。']],
 [['提前写条件','阶段门槛可以同时包括领域收益、旧能力退化、稳定性和预算。写清指标方向、评测集版本、允许变化与所需次数。门槛是学习实验的约定，不能照搬成通用上线标准。'],['看变化而不只看绝对值','有些阶段不需要把 loss 降到最低；继续追逐训练集可能使任务效果更差。结合验证曲线、固定失败集与多 seed/多样本波动，判断收益是否超过噪声。'],['冻结选择再测最终结果','选好 checkpoint、提示、解码参数后，才评估测试集。若根据测试失败继续改，原测试集已参与开发，应安排新的隔离评测或如实说明。']],
 ['先约定：领域指标改善、通用退化可接受、没有非有限 loss。','在验证集选 B 的第 200 步；保留第 100/300 步作诊断。','固定 B 后跑一次测试，报告样本数、误差和失败类型。'],
 ['为下一次实验写四项停止/进入条件，并填写指标来源。','另一人无需猜你想要什么，也能判断是继续、回退还是进入后训练。','只有“看起来不错”时，补上具体数据与比较对象。'],
 ['每次看测试集后修改配比，测试集角色发生什么变化？',['仍是完全独立最终测试','已经参与模型选择，需要承认或另设隔离测试','不会有影响'],1,'独立性来自使用方式，不来自文件名叫 test。'],['stages']),
 unit('midtrain-definitions','建立一份可以复查的术语对照，不背一条强制流水线。',[
 ['操作定义','用可观察的步骤说明词义，例如数据、目标与 checkpoint 关系。'],['来源范围','某个结论只适用于报告中具体版本和配置。']],
 [['先找作者的阶段图','Olmo 与 SmolLM 的公开材料展示了不同分期方式。本节让你比较文档中的阶段边界；不把 mid-training 简化为某一种固定算法。'],['将名字转成操作','长上下文适配、领域继续学习和推理能力强化，可能出现在不同报告的不同区间。识别它们时，优先检查样本格式、监督目标和初始化权重。CPT 描述一类操作，mid-training 描述配方中的位置，二者不能处处画等号。'],['把未知留在表里','公开报告未提供的参数范围、loss mask、训练时长不要猜测。后续读源码时可补齐；源码支持一种功能也不能证明该发布版本启用了它。']],
 ['左列写报告自己的阶段名，中列写数据与目标。','右列写来源链接、版本与未确认项。','只有操作相近时才做类比，并保留差异，不强制改名。'],
 ['对两个来源各选一个中间阶段，写出一项相同、一项不同、一项未知。','完成有证据的对照；能回答为什么“中训练=LoRA”不成立。','只读宣传摘要不足时，转到技术报告和训练数据说明。'],
 ['“仓库存在 long_context 配置”能证明当前模型使用过它吗？',['能','不能，还需对应 run/config/checkpoint 证据','只要目录名相同就能'],1,'功能支持、某次启用与实际效果是三层证据。'],['stages','mid']),
 unit('use-gap','在继续训练前，把用户需求变成可检验的行为。',[
 ['任务契约','输入、允许输出、正确性与失败处理的约定。'],['指令遵循','模型根据给定指令生成符合要求的输出，不等于事实一定正确。']],
 [['把“更好用”拆开','输出可解析 JSON、回答依据正确、不臆造工具结果、遇到缺信息能表达不确定，分别需要检查。一个总分不能说明这些能力从何而来。'],['先试不训练的对照','明确提示、约束解码、检索和程序校验可能解决一部分问题。保留这些基线，再比较训练收益；后训练不是所有问题的唯一入口。'],['从失败决定数据','格式失败可收集正确模板示范；内容质量有相对优劣可收偏好；程序任务能执行测试可产生可验证反馈。反馈类型决定后续可用路线，不能先指定算法再编造数据。']],
 ['要求返回 {"action":"move","x":0.2}。','字符串可解析只是第一关；还要验证 action 合法、x 范围和环境实际结果。','这三项分开记录，防止格式提升被当成任务成功。'],
 ['写一个任务契约，列出格式正确但任务失败的反例。','测试覆盖解析、语义、环境结果三层；没有环境时明确只验哪层。','不要用模型自己的“我已完成”作为成功证据。'],
 ['JSON 全部可解析，能证明任务全部完成吗？',['不能，还要检查含义与实际结果','能','只要训练 loss 很低就能'],0,'输出格式与世界中的结果是不同证据。'],['sft']),
 unit('post-routes','根据已有监督选择 SFT、偏好、奖励优化或蒸馏。',[
 ['示范','给定输入的期望输出。'],['偏好对','同一输入下两个候选的相对优劣。'],['奖励','对一次行为或轨迹的数值评价。']],
 [['示范告诉怎么做','SFT 提高示范输出的概率；覆盖范围、标签质量、mask 与模板很关键。示范不一定只有人写，也可能来自程序或模型，但来源与验证要记录。'],['比较告诉哪一个更好','偏好优化利用候选排序。DPO 的常见离线形式直接用固定偏好对和参考策略，不必单独拟合奖励模型，也不必在优化期间在线生成新回答。不要把它与在线采样 RL 的工程流程混为一谈。'],['反馈和教师提供另外两条路','RL 根据采样行为的奖励更新策略，必须处理探索、噪声和奖励漏洞。蒸馏让学生学习教师提供的答案或分布，质量受教师与学生访问分布影响。几条路线可以组合，但每次组合都需要额外验收。']],
 ['有 500 条可靠输入输出：先建 SFT 基线。','只有同题 A/B 比较：考虑偏好路线，并审查比较的一致性。','有可靠可执行测试：可比较 RL 路线；先确认模型有机会采到成功解。'],
 ['为一个任务写“已有信号→候选方法→最小基线→失败风险”的四列表。','不会因为听说 GRPO 新，就把所有数据强行变成奖励。','没有可靠信号时先建设数据/评测，而不是用训练掩盖未知。'],
 ['普通离线 DPO 必须先训练独立奖励模型吗？',['必须','不必，它可以直接优化固定偏好对','必须先训练一个世界模型'],1,'普通 DPO 省去显式奖励模型的这一环；具体变体另看配方。'],['sft','dpo']),
 unit('reward','认识奖励的来源、拟合方法以及被钻空子的风险。',[
 ['奖励模型 RM','输入候选及条件，输出评分的模型；它近似某个评价标准，不是正确性的保证。'],['奖励黑客','策略提高了代理奖励，却没有提高甚至损伤真实目标的现象。']],
 [['从偏好训练一个评分器','给同一问题的 chosen/rejected，令评分差 r(chosen)-r(rejected) 进入 sigmoid，再最小化 -log 概率。这样只约束相对分数，分数绝对值不能随意解释成正确率。'],['奖励也可以不是模型','代码测试、数学答案核对、任务成功信号都可形成规则反馈；人类偏好也可经奖励模型传递。所有来源都有边界：弱测试可能被过拟合，偏好标签可能不一致，评分器可能偏爱长度。'],['给奖励本身做评测','保留奖励验证集，检查排序准确率与分组偏差，再测试它是否给明显错误但长或迎合的回答高分。训练策略时同时监控独立任务评测，不能用同一个奖励证明自己可靠。']],
 ['评分差为 0：sigmoid=0.5，pairwise loss≈0.693。','差为 2：sigmoid≈0.881，loss≈0.127，排序更符合标签。','但这只能说明符合该偏好标签，不证明回答事实正确。'],
 ['给评分器设计三个对抗样例：长而错、短而对、格式正确但未完成。','评分标准能说明为什么排序；独立验收不会复用同一漏洞。','若只看平均 reward 上升，补上任务正确率与长度分布。'],
 ['奖励上涨、独立测试下降，最合理的下一步是？',['继续最大化奖励','检查代理目标、数据分布与奖励漏洞','删除独立测试'],1,'优化器只优化给它的信号，奖励必须接受独立检验。'],['dpo','ppo']),
 unit('rl-post','把语言生成接到“采样→评价→更新→再采样”的闭环。',[
 ['rollout','由当前策略产生的一次行为序列及其反馈。'],['策略梯度','通过提高高优势动作的概率、降低低优势动作概率来优化期望回报的一类方法。'],['优势 advantage','行为相对某个基准的好坏估计，可用于降低梯度估计方差。']],
 [['先读强化学习基础','如果状态、动作、回报仍陌生，先跳到本卷 5.3。本节把基础映射到语言：状态是问题和已有前缀，动作是下一个 token，完整回答得到奖励；不意味着每个 token 都有独立正确标签。'],['一次更新具体经过什么','从旧策略采样回答，保留采样时 log-probability；打分并计算回报/优势；当前策略对同样 token 计算 log-probability，再构造损失并更新。奖励或优势通常作为不求导的信号使用，不能误让梯度流进固定评分规则。'],['为什么要重新采样','策略更新后访问的回答分布变化，旧样本不再代表当前行为。大量重复利用旧样本会带来偏差或不稳定，因此算法设计采样与更新节奏、概率比和约束。KL 约束限制偏离参考的趋势，也不保证没有退化。']],
 ['同题采样回答 A/B，奖励分别 1/0。','若基准为 0.5，优势为 +0.5/-0.5：倾向提高 A、降低 B 的概率。','更新后重新采样并测成功率；一次概率变化不是完成整个 RL 训练。'],
 ['先实现 5.3 的回报，再实现下一节 PPO clipped surrogate，画出采样器/奖励/优化器三块。','能标明 old log-probability 从采样时保存，current log-probability 每次前向重算。','把教师强制的正确答案当作策略采样，会把 RL 流程误写成 SFT。'],
 ['为什么保留采样时的 old log-probability？',['用来和当前策略比较同一动作概率','作为永久不变的正确答案','用来计算 tokenizer 大小'],0,'概率比需要同一前缀、同一已采样动作的旧/新概率。'],['ppo','rl']),
 unit('ppo-grpo','区分反馈来源和优化算法，并手算一个裁剪目标。',[
 ['RLHF','从人类反馈获得优化信号的训练范式；不等于某一个优化器。'],['RLVR','采用可验证奖励的强化学习，如答案核对或测试。'],['PPO / GRPO','具体策略优化算法家族；GRPO 的原始设计利用同题一组回答的相对奖励估计优势。']],
 [['两条分类轴','RLHF/RLVR 说奖励从哪里来；PPO/GRPO 说怎样利用样本更新策略。PPO 常使用价值估计与优势；原始 GRPO 用组内相对奖励减少单独价值模型需求。不同实现的归一化、KL 和 token 聚合会变，不可只按名字复刻。'],['PPO 的一个局部目标','设 ratio=π_new(a|s)/π_old(a|s)，优势 A，epsilon=0.2。最大化 min(ratio×A, clip(ratio,0.8,1.2)×A)。最小化损失时再取负号。裁剪限制这个替代目标继续鼓励过大的有利更新，不是硬性限制所有概率变化。'],['组内相对奖励也有失败情形','同题全部回答奖励相同，中心化信号可能为零；标准化要处理零方差。判分噪声、长度偏差和弱测试也会污染优势。GRPO 不会自动让错误奖励变可靠，PPO 也不保证每次提升。']],
 ['ratio=1.5，A=2：min(3,2.4)=2.4。','ratio=0.5，A=-2：min(-1,-1.6)=-1.6，注意负优势方向。','全部奖励 [1,1,1]：减均值后全零；不能除以零标准差。'],
 ['实现下方裁剪目标，分别画正、负优势时 ratio 从 0.5 到 1.5 的数值。','正确处理负优势；明确返回最大化目标，不要与负 loss 混淆。','只写 clip(ratio)×A 会在部分区间出错；必须保留 min。'],
 ['RLVR 与 GRPO 的关系是？',['同义词','前者描述反馈来源，后者描述优化方式','都指模型结构'],1,'同一反馈范式可以搭配不同算法；实际组合还要检查实现。'],['ppo','grpo'],{exerciseId:'book-ppo'}),
 unit('distillation','从复制教师答案，走到让教师评价学生自己访问的上下文。',[
 ['蒸馏','把教师的输出或分布作为学生的学习信号。'],['On-policy distillation / OPD','学生按自身策略产生样本或上下文，再由教师提供匹配信号的一类蒸馏路线。'],['MOPD','本书指 Multi-Teacher On-Policy Distillation；需与其他同名缩写区分。']],
 [['先理解离线答案蒸馏','教师离线生成输入输出对，学生可用 SFT 学习。简单、可复用，但学生部署时会遇到自己的错误前缀，未必与教师生成数据分布一致。'],['换成学生访问的分布','学生自己生成 token 或轨迹；教师在相同前缀评价这些 token。教师和学生概率必须对齐同一个 token，而不是各取自己的最高概率 token 再相减。KL 方向、采样方式与梯度估计需按具体算法确认。'],['多个教师怎样接入','MOPD 的代表配方先形成领域教师，再让学生的样本由匹配教师提供信号，最后逐域评测整合效果。课程的机器人实验用解析冻结教师、两步学生上下文和全分布 KL；它是机制实验，不是领域 RL 教师或完整语言模型论文复现。']],
 ['学生采样 token x：log p_student=-2，教师对同一个 x 为 -1。','teacher-student 信号为 +1，表示教师相对更认可该已采样 token。','多个领域要分别报告指标；平均变好仍可能损伤某个教师擅长的能力。'],
 ['运行 MOPD 机制题，检查 prompt/tool/padding mask；再读公开参考工程中的教师路由。','知道为什么需要学生采样、同前缀同 token、逐域验收。','信号均值不是完整 reverse KL；不要拿单个 token 的差值当整个分布距离。'],
 ['教师与学生 log-probability 应该评价什么？',['各自最喜欢的不同 token','相同前缀下同一个学生采样 token','随便一个词'],1,'否则差值不再表达对同一个行为的相对评价。'],['mopd'],{exerciseId:'journey-distill-signal',links:[['多教师实验带练','journey','mopd']]}),
 unit('modality-post','把后训练思路迁移到图像、视频和行为，同时保留各自目标。',[
 ['生成适配','在已有生成模型上，用目标数据或反馈改变风格、条件匹配或质量。'],['行为克隆 BC','从观测/动作示范学习策略，是模仿学习的一种常见形式。']],
 [['图像：监督损失通常不长得像语言 SFT','在图像文字对上继续训练已有扩散模型，可沿用去噪目标；也可采用偏好或奖励微调。LoRA 只指定更新参数的形式，不决定用 token 交叉熵还是去噪误差。“SFT”在不同团队中可能泛指监督适配，必须落实到公式。'],['视频：还要保持时间一致性','单帧美观奖励容易偏离时序、运动或物理一致性。微调时采样整段片段，检查文字一致、主体持续、动作连贯与多样性。只看精选视频不能代表整体改进。'],['具身：评价最终落在环境','示范动作可训练策略，奖励可来自环境成功与代价。离线动作误差小不代表闭环任务成功：状态分布会随策略变化。先在固定模拟任务与扰动条件比较，再讨论更复杂部署。']],
 ['语言：问题/答案，监督回答 token。','图像：文字/目标图，监督噪声或速度；训练 LoRA 仍可保持该目标。','机器人：观测/动作轨迹，先 BC，再按可用反馈比较其他方法。'],
 ['选一种模态，填“输入→预测对象→loss→可训练参数→独立评测”。','不会写成“所有模态的后训练都用语言 SFT loss”。','本平台二维 Flow 与策略机制可运行；完整图像/视频后训练尚未接入，不能把机制成绩当成复现。'],
 ['对扩散模型使用 LoRA，训练目标必然变成交叉熵吗？',['会','不会，更新范围与目标是不同选择','会变成 KDA'],1,'LoRA 可以用于不同监督目标；必须检查具体实现。'],['draft','lora']),
 unit('post-eval','用多层评测发现“更像好答案”却更不可靠的情况。',[
 ['回归评测','修改后重新检查已有能力是否退化。'],['评测污染','训练或调参获得了本应隔离的测试信息，导致结果高估。']],
 [['固定可比较条件','同一题集、提示模板、采样设置、最大长度与评测程序，才有可解释的前后比较。记录模型 checkpoint 和 adapter；忘记加载适配器会让实验变成测基座。'],['将改善拆成不同层','格式、答案正确、偏好、事实性、工具成功与成本分别报告。若长回答更讨评分器喜欢，需要长度分组或人工抽样；若训练集题复现好，换独立模板与实体测试泛化。'],['失败样例指导下一步','格式错误查模板/mask；事实错误查知识证据与数据；任务闭环失败查接口和环境；全部域退化查学习率、实现、checkpoint。先定位，再决定加数据、换目标还是回退。']],
 ['SFT 后 JSON 可解析率提升，但合法动作率未变。','偏好后平均评分升高，但答案变长、延迟上升。','报告两者，而不是把一个改善写成“模型全面增强”。'],
 ['在实验手记创建固定评测表，至少保留一个提升项、一个退化项和两个失败样例位置。','没有退化时也记录检查过哪些域，不宣称检查不到的能力都保持。','不要修改评测规则来追认某次实验成功；修改时重跑全部对照。'],
 ['调整了采样温度后分数提高，可以直接归因于新权重吗？',['可以','不能，解码策略也是变量','只要名字叫 SFT 就可以'],1,'权重和推理设置要分开比较。'],['sft','dpo']),
 unit('freezing','沿计算图检查哪些参数有梯度、被优化器持有并真正更新。',[
 ['冻结','阻止指定参数更新；不必等于整段前向都无需构建计算图。'],['可训练参数','允许求梯度且被正确纳入优化步骤的参数。']],
 [['三个问题逐一查','requires_grad 是否开启？优化器参数组是否包含它？反向传播后梯度是否非空并在 step 后变化？只打印总参数量不能证明某模块正在学习。'],['冻结也可能需要传梯度','如果冻结模块前面有可训练投影层，仍可能需要梯度穿过冻结模块传回投影层。把整个路径放进 no_grad 会切断信号。参数不求导与输出不建图不是同一件事。'],['节省什么、还剩什么','冻结减少梯度与优化器状态成本，但激活、前向与底座存储仍可能占用很多资源。PEFT 应报告可训练参数、实际显存、吞吐与质量，不能只用参数比例推断速度倍数。']],
 ['W 冻结，A/B 可训练；前向 y=Wx+B(Ax)。','检查 A/B 在 optimizer 中，W 不发生变化。','如果 B 初始为零，第一步 A 的梯度可能为零；应结合初始化与后续步诊断。'],
 ['进入 LoRA 工作坊，运行参数冻结检查；故意漏掉一个参数组，看测试是否暴露问题。','能证明更新范围，而不只相信配置名字。','loss 下降也不能证明所有目标模块在学；对比参数前后快照。'],
 ['冻结参数和整个模块使用 no_grad 完全相同吗？',['相同','不同，后者可能截断对上游可训练模块的梯度','冻结会自动删除模块'],1,'梯度是否需要穿过该模块取决于整个计算图。'],['lora'],{links:[['SFT / LoRA 实战','projects','workshop-sft-lora']]}),
 unit('rl-basics','从一个两步环境理解策略、奖励、回报与探索，再读高级算法。',[
 ['状态 s','决策时可用的信息；看不全环境时通常是观测及历史。'],['动作 a 与策略 π','动作是一次选择；策略把可用信息映射到动作概率或动作。'],['奖励 r 与回报 G','奖励是一时反馈；回报是从当前开始的未来奖励加权和。']],
 [['先让选择改变后续','想象到达目标得 2 分，中间走一步得 0 分。只盯即时奖励会认为第一步毫无价值，但它使第二步成功成为可能。RL 试图优化长期回报；示范学习则直接告诉每个状态应做哪个动作。'],['手算折扣回报','定义 G_t=r_t+γG_(t+1)，终点之后回报为 0；γ 在 0 到 1。奖励 [0,2]、γ=0.9，最后一步 G=2，前一步 G=1.8。倒序累计避免反复求和，改变 γ 改变对远期奖励的权重。'],['策略怎样得到学习信号','最简单的策略梯度用 -log π(a|s)×优势作为损失项，优势可用回报减去不依赖当前采样动作的基准估计。高于预期的动作更可能被重复。实际算法还要控制方差、分布变化与约束。'],['为什么需要探索','从不尝试某个动作就难以知道它的后果；但随机尝试也有成本。先在小环境中观察采样与奖励，不把“训练 loss 下降”当作成功率保证。世界模型负责预测，策略负责选择；RL 可以使用世界模型，也可以不使用。']],
 ['奖励 [1,0,2]、γ=0.5：G2=2，G1=1，G0=1.5。','γ=0：每步只看当前奖励；γ=1：有限轨迹直接累计后续奖励。','相同策略多次采样可能得到不同回报；要重复评测而非展示一次成功。'],
 ['实现下方回报函数，测试空轨迹、γ=0、γ=1；再用纸写出一次采样→评价→更新。','参考输出 [1.5,1,2]；不修改输入列表。能区分单步 reward 与未来 return。','从前往后直接累加会算成过去奖励；本题要从结尾反向计算未来回报。'],
 ['奖励 [0,2]、γ=0.9，第一个动作的回报是多少？',['0','1.8','2.9'],1,'G0=0+0.9×2=1.8，第一步因促成未来成功而获得学习信号。'],['rl','ppo'],{exerciseId:'book-returns',links:[['回到强化学习后训练','book','training/posttrain/rl-post']]}),
 unit('combinations','为组合方法检查数据契约、梯度、目标和部署产物。',[
 ['兼容性','模块与训练方法在输入、输出、梯度和状态等方面满足约定。'],['消融','固定其他因素，只移除或改变一个因素来检验贡献。']],
 [['先确认层级','SFT+LoRA 是任务目标与更新范围的组合；视觉塔+语言骨干是接口组合；RLVR+GRPO 是反馈与优化组合。能写在同一句里不等于实现已兼容。'],['再追一条样本和一次更新','模板中的图像占位符如何对应视觉特征？loss mask 是否覆盖回答/动作？reference 与 policy 是否加载正确版本？adapter 是否被 optimizer 更新？推理是否加载相同 tokenizer 与权重？逐项给证据。'],['最后比较成本与收益','先有最简单的可复现基线，再增加一个组件。若同时更换数据、结构和 loss，即使变好也无法判断组合中谁有贡献。对于暂时无法消融的成本，明确结论边界。']],
 ['基线：全量 SFT。对照：相同数据、预算和评测，改为 LoRA。','另一个实验再换偏好目标，不能把其提升算到 LoRA。','部署时对比加载 adapter 前后固定输入输出，核对产物来源。'],
 ['为自己的组合列四个接口断言，并挑一个故意破坏以验证检查会失败。','检查确实捕获错误，例如全部 mask 为零、adapter 未载入。','只写“兼容 Transformer”不够，必须落实到张量与状态。'],
 ['比较 LoRA 与全量更新时，同时更换训练数据会怎样？',['更容易归因','无法把变化单独归因于更新方式','不会有影响'],1,'消融需要控制可能影响结果的变量。'],['lora','sft']),
 unit('growth-base','用无需 GPU 的小模型，建立可追踪的阶段实验起点。',[
 ['计数基线','从样本统计条件频率得到模型，用来理解概率预测；不是 Transformer。'],['NLL','负对数似然，正确目标分配概率越高通常越小；比较时需固定编码与评测。']],
 [['为什么先用一个小实验','完整基座训练很贵，先用一阶字符转移计数器看清阶段、数据混合与评测。它只记前一个字符，无法理解长指令；我们只验证实验流程与分布权衡，不宣称复现大模型能力。'],['运行会产生什么','下载实战代码后，运行 projects/lifecycle-lab/lifecycle.py。脚本内置公开教学字符串，固定训练/评测样本，输出 base、mixed、domain_only、task_demo 四个模型快照与分域报告。计数平滑保证概率非零。'],['建立基线表','先读 base 的通用、领域 NLL 与固定 prompt 的输出，再看后续阶段。记录数据版本、混合权重和参数表大小。这个模型没有梯度优化器，不能用它学习 Adam 或真实 SFT mask；这些由 P01/P02 补齐。']],
 ['输入上下文“a”，计数下一字符并加平滑，得到条件分布。','给评测字符串逐字符取目标概率，累加 -log p 再平均。','保存 base.json 后，再从相同 base 分叉继续实验。'],
 ['运行下方命令，找到 report.json 和四个快照；不要只读终端最后一行。','报告包含同一套通用/领域/任务评测与每阶段数据说明；能从 JSON 重载模型。','若想学真实梯度预训练，转到 P01；不要把增加计数当作神经网络反向传播。'],
 ['此实验的合理结论范围是？',['已复现大模型完整 SFT/RL','观察阶段、分布变化与固定评测的方法','可直接证明生产模型最佳配比'],1,'微型机制帮助控制变量，能力与成本不能直接外推。'],['stages'],{command:'python3 projects/lifecycle-lab/lifecycle.py --out .openai/local/lifecycle',links:[['真实 PyTorch 语言预训练','projects','workshop-pretrain']]}),
 unit('growth-mid','从同一起点建立两条持续学习分支。',[
 ['实验分叉','复制同一基座，独立实施不同改动，避免先后顺序混入比较。'],['有效权重','本实验通过样本计数权重模拟数据混合；不等于真实 token 采样轨迹。']],
 [['先写预期再看报告','mixed 混入通用与领域数据，domain_only 只加领域数据，新增总计数权重相同。猜想领域更多会改善领域预测，但可能改变通用预测；结果由固定评测决定，不预设一定符合猜想。'],['检查真的只改了一项','脚本使用同一 base 的深拷贝，保持字符表、平滑与总追加权重。真实模型中还需控制优化器状态、随机种子、batch 与 token 预算，这里只模拟其中的数据因素。'],['找收益从哪里来','查看条件分布变化和分域 NLL。改善可能来自高频转移更贴合领域，而不是学会推理。尝试给数据加入重复行，观察为何数量不能直接等同独立信息。']],
 ['base→mixed，base→domain_only：两条平行分支。','两分支新增总权重相同，数据来源比例不同。','固定评测后比较领域收益和通用保留；不改权重来挑赢家。'],
 ['修改 --domain-share 为 0.2/0.5/0.8，分别输出到不同目录，写一张分域表。','每份报告都保留参数和样本数，可以重建设置；观察而非保证趋势。','若输出覆盖导致无法比较，先分目录再重跑，不能从记忆补数值。'],
 ['为什么不能用 mixed 接着训练 domain_only 再直接比较？',['它多了训练历史和预算','因为文件名不一样','领域数据不能重复'],0,'顺序会混入额外变量，应该从相同基座分叉。'],['mid'],{command:'python3 projects/lifecycle-lab/lifecycle.py --domain-share 0.8 --out .openai/local/lifecycle-80'}),
 unit('growth-post','根据反馈类型挑选一条后训练路线，并指出微型实验的边界。',[
 ['任务示范适配','用目标格式与输入输出示例改变模型行为分布。'],['监督区域','哪些位置的预测误差进入训练目标，语言 SFT 常重点监督回答区域。']],
 [['微型实验只做什么','task_demo 阶段从 mixed 出发增加固定格式示范。计数器会更常生成格式中的字符片段，却没有完整问答上下文，也没有语言 SFT 的回答 mask。因此脚本标为“任务示范分布适配”，不冒充完整 SFT。'],['转到真实 SFT 时补什么','P02 提供数据模板、回答 mask、tokenizer、全量/LoRA 更新与可选真实基座训练器。先通过离线契约检查，再按设备下载允许使用的权重，记录版本和实际训练结果。接口测试通过不等于权重已训练成功。'],['如果只有奖励怎么办','先回到 RL 基础，检查反馈是否可验证、模型是否能采到有意义样本。若只有偏好对，先比较 P03 的离散 DPO 机制。每条路线单独设基线，不必强行把全部算法串成一次训练。']],
 ['统计器的 task_demo：观察格式分布变化，能力有限。','真实 SFT：对问答样本进行正确位置的梯度更新。','偏好/RL：换学习信号，还要增加参考策略或 rollout 等组件。'],
 ['先运行 task_demo 报告，再完成 P02 的回答 mask 与冻结检查；把两者差异写入手记。','能说清“目标格式出现更多”与“完成用户任务”之间还差什么。','如果用计数器输出证明模型懂指令，结论已超出模型信息容量。'],
 ['task_demo 的分布变化可被称为完整语言 SFT 复现吗？',['可以','不可以，缺少上下文能力与真实 SFT 训练契约','只要输出 JSON 就可以'],1,'实验必须按真实能力命名，不能把类比包装成完整复现。'],['sft'],{links:[['SFT 的回答监督与训练器','projects','workshop-sft-lora'],['偏好机制实战','projects','workshop-preference']]}),
 unit('growth-compare','把多个快照变成一个可解释的实验结论。',[
 ['实验谱系','每个产物来自哪个起点、哪些数据和何种改动的关系。'],['适用范围','结论成立的模型、数据、预算和评测条件。']],
 [['先整理产物再写结论','报告列出 checkpoint、父节点、数据版本、混合参数与各域指标。配合阶段图检查是否真的从同一起点分叉。可重载 JSON 复算 NLL，避免终端截图成为唯一证据。'],['按问题回答','领域预测改善多少？通用能力退化多少？格式示范的收益在哪里？参数规模和预算是否相同？最后才说选择哪个快照。不要把相同单位的指标随意相加，也不要隐藏未达成的门槛。'],['提出下一次最小改动','如果长依赖是主要失败，一阶模型再加同类数据可能无效，应回到第三卷更换序列结构；如果监督错位，先修数据；如果方差大，补重复实验。下一步由失败证据推动，而不是跟随新名词。']],
 ['事实：固定评测上某分支领域 NLL 降低。','解释：可能更贴合领域转移频率；用分布分析支持。','边界：只是一阶字符模型与教学数据，不代表真实大模型的最佳配方。'],
 ['提交阶段图、分域表、两个失败样例和下一步假设；在实验手记中保存文件位置。','别人能按命令得到同一报告，知道你证明了什么、还没证明什么。','只有“变好了”时，把比较起点、指标方向、数字和数据范围补齐。'],
 ['训练结果支持的结论应该怎样写？',['对所有模型都成立','限定模型、数据、预算与评测，并区分事实和解释','只写最高分'],1,'可复查的边界是可靠研究结论的一部分。'],['stages'])
];
